    for item in descriptor["source_manifest"]:
        packet = json.loads((root / item["local_path"]).read_text(encoding="utf-8"))
        line, quote = next(
            (index, text)
            for index, text in enumerate(packet["content"].splitlines(), 1)
            if len(text.strip()) >= 4
        )
        result.append(
            {
                "source_id": item["id"],
                "source_sha256": item["source_sha256"],
                "line_start": line,
                "line_end": line,
                "quote": quote,
            }
        )
    return result


